from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != bg or (sr,sc) in seen: continue
            q=deque([(sr,sc)]); seen.add((sr,sc)); cells=[]
            r0=r1=sr; c0=c1=sc
            while q:
                r,c=q.popleft(); cells.append((r,c))
                r0=min(r0,r); r1=max(r1,r); c0=min(c0,c); c1=max(c1,c)
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=r+dr,c+dc
                    if 0<=nr<h and 0<=nc<w and grid[nr][nc]==bg and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            # Fill rectangular pockets fully bounded by the foreground or grid edge.
            if len(cells) != (r1-r0+1)*(c1-c0+1): continue
            sides=[]
            for c in (c0-1,c1+1):
                sides.append(all(not (0<=c<w) or grid[r][c] != bg for r in range(r0,r1+1)))
            for r in (r0-1,r1+1):
                sides.append(all(not (0<=r<h) or grid[r][c] != bg for c in range(c0,c1+1)))
            solid_sides=0
            for c in (c0-1,c1+1):
                if 0<=c<w and all(grid[r][c] != bg for r in range(r0,r1+1)): solid_sides += 1
            for r in (r0-1,r1+1):
                if 0<=r<h and all(grid[r][c] != bg for c in range(c0,c1+1)): solid_sides += 1
            if all(sides) and solid_sides >= 3:
                for r,c in cells: out[r][c]=4
    return out
